insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"wh_questions_q01_finish","speaker_external_id":"Ghost","source_path":"_registry\\dialogues\\wh_questions.yaml","source_metadata":{}},{"key":"wh_questions_q01_start","speaker_external_id":"Ghost","source_path":"_registry\\dialogues\\wh_questions.yaml","source_metadata":{}},{"key":"wh_questions_q02_finish","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\wh_questions.yaml","source_metadata":{}},{"key":"wh_questions_q02_start","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\wh_questions.yaml","source_metadata":{}},{"key":"wh_questions_q03_finish","speaker_external_id":"Cannoneer","source_path":"_registry\\dialogues\\wh_questions.yaml","source_metadata":{}},{"key":"wh_questions_q03_start","speaker_external_id":"Cannoneer","source_path":"_registry\\dialogues\\wh_questions.yaml","source_metadata":{}},{"key":"wh_questions_q04_finish","speaker_external_id":"Little Girl","source_path":"_registry\\dialogues\\wh_questions.yaml","source_metadata":{}},{"key":"wh_questions_q04_start","speaker_external_id":"Little Girl","source_path":"_registry\\dialogues\\wh_questions.yaml","source_metadata":{}},{"key":"wh_questions_q05_finish","speaker_external_id":"Mountain Guide","source_path":"_registry\\dialogues\\wh_questions.yaml","source_metadata":{}},{"key":"wh_questions_q05_start","speaker_external_id":"Mountain Guide","source_path":"_registry\\dialogues\\wh_questions.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"wh_questions_q01_finish","locale":"he","line_order":0,"content":"רגע. אני נזכרת בספינה על המים, ובשם שקראו לי בלילה ההוא.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q01_finish","locale":"he","line_order":1,"content":"נמו Nemo דג במפרץ באותו ערב. אולי הוא ראה מי הייתה שם. לכו אליו.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q01_start","locale":"he","line_order":0,"content":"שלום. אני רוח קטנה, ואני לא זוכרת מי אני. אני זוכרת רק ים וסערה.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q01_start","locale":"he","line_order":1,"content":"כדי להיזכר צריך לשאול שאלות מידע. שאלת מידע = Wh-question. היא מתחילה במילת שאלה ומבקשת מידע, ולא תשובה של כן או לא.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q01_start","locale":"he","line_order":2,"content":"נתחיל בשתיים. What = מה, שואלים על דבר. Where = איפה, שואלים על מקום.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q01_start","locale":"he","line_order":3,"content":"בואו נמצא את החלק הראשון בזיכרון שלי.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q02_finish","locale":"he","line_order":0,"content":"עכשיו זה ברור. מלחה צעירה עמדה על הסיפון, והסערה הגיעה אחרי חצות.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q02_finish","locale":"he","line_order":1,"content":"התותחן במפרץ הנטוש שמע רעש גדול באותו לילה. הוא יודע למה זה קרה.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q02_start","locale":"he","line_order":0,"content":"רוח? כן, אני זוכר את הלילה הזה. הרשת שלי נקרעה מהרוח החזקה.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q02_start","locale":"he","line_order":1,"content":"אבל אני לא זוכר מי עמדה על הסיפון ובאיזו שעה זה קרה.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q02_start","locale":"he","line_order":2,"content":"Who = מי, שואלים על אדם. When = מתי, שואלים על זמן.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q02_start","locale":"he","line_order":3,"content":"עזרו לי לשאול נכון, ואני אספר לכם את כל מה שראיתי.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q03_finish","locale":"he","line_order":0,"content":"עכשיו הסיפור מסתדר. הרוח החזקה שברה את התורן, והספינה לא הצליחה לחזור.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q03_finish","locale":"he","line_order":1,"content":"הילדה הקטנה מחכה מתחת לעץ הכתום הגדול. היא אוספת שאלות בשביל הרוח.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q03_start","locale":"he","line_order":0,"content":"שמעתי רעש נורא מהמים, ומאז אני שואל את עצמי שאלה אחת שוב ושוב.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q03_start","locale":"he","line_order":1,"content":"Why = למה, שואלים על סיבה. How = איך, שואלים על האופן שבו משהו קורה.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q03_start","locale":"he","line_order":2,"content":"שתי המילים נשמעות דומות בסיפור, אבל הן מחפשות דברים שונים.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q03_start","locale":"he","line_order":3,"content":"עזרו לי, ונדע למה הספינה נשברה.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q04_finish","locale":"he","line_order":0,"content":"וואו, עכשיו כל שאלה נשמעת נכון. אני אשמור את המחברת בשביל הרוח.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q04_finish","locale":"he","line_order":1,"content":"מדריך ההרים מדליק מדורה במגדל בכל לילה. שם אפשר לספר לרוח את כל הסיפור.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q04_start","locale":"he","line_order":0,"content":"אמא אמרה שאסור לדבר עם רוחות, אבל אני רוצה לעזור לרוח העצובה.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q04_start","locale":"he","line_order":1,"content":"אני יושבת כאן מתחת לעץ הכתום הגדול וכותבת שאלות במחברת.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q04_start","locale":"he","line_order":2,"content":"רק שכל השאלות שלי מתחילות בצורה לא נכונה.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q04_start","locale":"he","line_order":3,"content":"בשאלת מידע מילת השאלה תמיד עומדת בהתחלה, ואחריה שאר המשפט.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q04_start","locale":"he","line_order":4,"content":"בואו נסדר את השאלות שלי יחד.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q05_finish","locale":"he","line_order":0,"content":"הרוח שמעה את הסיפור המלא, והיא נרגעת מול האש. קוראים לה בו Boo.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q05_finish","locale":"he","line_order":1,"content":"עשיתם עבודת חקירה מצוינת עם כל מילות השאלה.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q05_finish","locale":"he","line_order":2,"content":"קבלו עשרה מטבעות עכשיו. סיימתם את הסיפור בהצלחה!","line_format":"plain_text"},{"dialogue_key":"wh_questions_q05_start","locale":"he","line_order":0,"content":"המדורה דולקת, והרוח כבר מחכה כאן. חסר רק דבר אחד.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q05_start","locale":"he","line_order":1,"content":"צריך לשאול את כל שש השאלות בקול, כדי שהסיפור יהיה שלם.","line_format":"plain_text"},{"dialogue_key":"wh_questions_q05_start","locale":"he","line_order":2,"content":"What, Where, When, Who, Why, How. הפעם הכול מעורבב יחד.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
